1	type Cell = [number, number]; // [x, y]
2	
3	const NEIGHBOR_OFFSETS: Cell[] = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [0, -1], [0, 1],
6	  [1, -1], [1, 0], [1, 1],
7	];
8	
9	const keyOf = ([x, y]: Cell): string => `${x},${y}`;
10	
11	export function nextGeneration(cells: Cell[]): Cell[] {
12	  const alive = new Set(cells.map(keyOf));
13	  const neighborCounts = new Map<string, number>();
14	
15	  for (const [x, y] of cells) {
16	    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
17	      const neighbor = keyOf([x + dx, y + dy]);
18	      neighborCounts.set(neighbor, (neighborCounts.get(neighbor) ?? 0) + 1);
19	    }
20	  }
21	
22	  const survives = (key: string, count: number): boolean =>
23	    count === 3 || (count === 2 && alive.has(key));
24	
25	  const next: Cell[] = [];
26	  for (const [key, count] of neighborCounts) {
27	    if (survives(key, count)) {
28	      const [x, y] = key.split(",").map(Number);
29	      next.push([x, y]);
30	    }
31	  }
32	
33	  return next;
34	}
